/// <summary>
/// MPJ_11539 - kscerri - 27/07/2021
/// Class <c>METPrintMgmtReportFormatPopulatorAppSuite_Extension</c> populates the PrintMgmtReportFormat table used for print management 
/// with the documents.
/// </summary>
[ExtensionOf(classStr(PrintMgmtReportFormatPopulator))]
public final class METPrintMgmtReportFormatPopulatorAppSuite_Extension
{
    #ISOCountryRegionCodes
    #PrintMgmtSetup

}

Method.Source:
    /// <summary>
    /// MPJ_11539 - kscerri - 27/07/2021
    /// adds documents
    /// </summary>
    protected void addDocuments()
    {
        this.customAddSalesDocuments();

        // MPJ_17952_PBMSReports1
        this.addOther(PrintMgmtDocumentType::PurchaseOrderConfirmationRequest, ssrsReportStr(METPurchPurchaseOrder, Food), ssrsReportStr(METPurchPurchaseOrder, Food), #NoCountryRegionId);
        this.addOther(PrintMgmtDocumentType::PurchaseOrderConfirmationRequest, ssrsReportStr(METPurchPurchaseOrder, Hardware), ssrsReportStr(METPurchPurchaseOrder, Hardware), #NoCountryRegionId);
        this.addOther(PrintMgmtDocumentType::PurchaseOrderConfirmationRequest, ssrsReportStr(METPurchPurchaseOrder, Liquor), ssrsReportStr(METPurchPurchaseOrder, Liquor), #NoCountryRegionId);

        this.addOther(PrintMgmtDocumentType::PurchaseOrderRequisition, ssrsReportStr(METPurchPurchaseOrder, Food), ssrsReportStr(METPurchPurchaseOrder, Food), #NoCountryRegionId);
        this.addOther(PrintMgmtDocumentType::PurchaseOrderRequisition, ssrsReportStr(METPurchPurchaseOrder, Hardware), ssrsReportStr(METPurchPurchaseOrder, Hardware), #NoCountryRegionId);
        this.addOther(PrintMgmtDocumentType::PurchaseOrderRequisition, ssrsReportStr(METPurchPurchaseOrder, Liquor), ssrsReportStr(METPurchPurchaseOrder, Liquor), #NoCountryRegionId);

        next addDocuments();
    }

    /// <summary>
    /// MPJ_11539 - kscerri - 27/07/2021
    /// Adds sales records to the PrintMgmtReportFormat table.
    /// </summary>
    private void customAddSalesDocuments()
    {
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::METCustActivityStatement, ssrsReportStr(METCustActivityStatement, Report), ssrsReportStr(METCustActivityStatement, Report), #NoCountryRegionId, true);
        
        //MPJ_15231_Customer Statement DCP 17/05/2022
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::METCustActivityStatementMulti, ssrsReportStr(METCustActivityStatement, ReportMulti), ssrsReportStr(METCustActivityStatement, ReportMulti), #NoCountryRegionId, true);
    
        
        // MPJ_17952_PBMSReports1
        this.addOther(PrintMgmtDocumentType::SalesOrderInvoice, ssrsReportStr(METSalesInvoice, Liquor), ssrsReportStr(METSalesInvoice, Liquor), #NoCountryRegionId);
        this.addOther(PrintMgmtDocumentType::SalesOrderInvoice, ssrsReportStr(METSalesInvoice, Food), ssrsReportStr(METSalesInvoice, Food), #NoCountryRegionId);
        this.addOther(PrintMgmtDocumentType::SalesOrderInvoice, ssrsReportStr(METSalesInvoice, Hardware), ssrsReportStr(METSalesInvoice, Hardware), #NoCountryRegionId);


    }
